pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize proportionally to how unusable it is.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.6 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Global residual pressure: if mean residual is small, protect tight bins;
    // if mean residual is large, be pickier about accepting sloppy fits.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.3 * mean_gap;

    // Time horizon: early on, allow more exploration (mild new-bin tolerance);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0;
    score -= progress * 8.0;

    // New-bin candidate: only attractive when item barely fits anywhere or bin is fresh
    // and item is small (preserving flexibility for large future items).
    if bin_residual == bin_capacity {
        let small_item_bonus = (bin_capacity - item_size) as f64;
        let open_pressure = open_bins_count as f64;
        score = 25.0 + small_item_bonus * 0.3 - open_pressure * 2.0 - progress * 10.0;
        if next_item_size > 0 && item_size >= next_item_size {
            // Opening a fresh bin for a large item before a smaller one is fine.
            score -= 5.0;
        }
    }

    // Slight preference for leaving perfectly reusable residuals (e.g. multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0;
        } else if post_residual >= 50 {
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 950.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure with progress relaxation.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0 * (1.0 - progress);
    }

    // Lookahead chain bonus: reward when next item exactly or nearly fills
    // the leftover; penalize unusable leftovers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 150.0 - 0.75 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 9 {
                bonus += 70.0;
                if after_next <= 3 {
                    bonus += 30.0;
                }
            } else if after_next >= 9 && after_next < 20 {
                bonus -= 8.0;
            } else if after_next >= 20 && after_next <= 35 {
                bonus += 12.0;
            }
            if next_item_size > bin_capacity / 2 {
                bonus += 30.0;
            }
            if fitting_bins_count <= 2 {
                bonus += 46.0;
            }
            if after_next > 0 && after_next < item_size {
                bonus -= 20.0;
            }
            if after_next > 0 && after_next < next_item_size / 4 {
                bonus += 14.0;
            }
            if after_next == 0 {
                bonus += 25.0;
            }
            if after_next > 0 && after_next < 40 && (after_next as f64) < 0.06 * cap {
                bonus += 10.0;
            }
            if after_next > 0 && (after_next as f64) > 0.5 * cap && next_item_size <= bin_capacity / 2 {
                bonus += 18.0;
            }
            score -= bonus;
        } else {
            // Next item cannot use leftover: penalize proportional waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.38 * overshoot + 0.28 * (bin_residual as f64 - mean_residual).abs();
            if overshoot < 6.0 {
                score += 22.0;
            }
        }
    }

    // Mean-residual coupling.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Dead-space pressure relative to mean, with chain relaxation.
    let dead = (post_residual as f64 - mean_residual).max(0.0);
    let chains = next_item_size > 0 && post_residual >= next_item_size;
    score += if chains { 0.22 } else { 0.6 } * dead;

    // Late-stage fill pressure: discourage leaving large unused capacity.
    let dead_ratio = 1.0 - post_residual as f64 / cap;
    score -= 28.0 * progress * dead_ratio;

    // Large-bin late fill: prefer placing small items into spacious bins.
    if bin_residual > 3 * bin_capacity / 4 && item_size < bin_residual / 2 {
        score -= 14.0;
    }

    // New-bin candidate: open fresh bin only when scarcity or big next item
    // justifies it; discourage when many bins are open or late in stream.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 125.0 } else if fitting_bins_count == 2 { 40.0 } else { 0.0 };
        let big_next = if next_item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        let many_open = if open_bins_count > 12 { 12.0 } else { 0.0 };
        score -= scarcity + big_next + many_open;
        score += 24.0 * progress + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 45.0;
        }
    }

    // Small item into near-doomed residual: discourage early, allow late.
    if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // Nearly-chainable leftover: nudge toward fits that keep chains alive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
        score -= 10.0;
    }

    score
}

