pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste shaping: penalize residuals that are too small to be useful
    let norm_post = post / cap; // in [0,1]
    let dead_zone = (1.0 - norm_post).powi(6); // grows sharply as residual shrinks
    score += dead_zone * cap * 0.35;

    // Smooth cubic coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (fewer chances to recover)
    let tightness = (norm_post * (1.0 - norm_post) * 4.0).powi(2); // peaks at residual = cap/2
    score -= tightness * cap * (0.10 + 0.25 * progress);

    // Lookahead: reward bins whose post_residual accommodates the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack).powi(2) * cap * 0.30 * (0.5 + 0.5 * progress);
        } else {
            let gap = (nxt - post) / cap;
            score += gap.powi(2) * cap * 0.20;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.25 * (0.3 + 0.7 * progress);
    }

    // Mild preference toward consolidating into fuller bins as open-bin count grows
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score -= (bin_residual as f64 / cap).powi(3) * cap * 0.15 * crowding;

    // Divergence from mean residual: prefer bins near the mean to keep options open
    let dev = (post - mean_residual) / cap;
    score += dev.abs().powi(2) * cap * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain fit is gold
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 120.0 - 0.6 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 6 {
                bonus += 60.0;
            }
            // large next items deserve priority placement
            if next_item_size > bin_capacity / 2 {
                bonus += 25.0;
            }
            // reward near-perfect double fill: item + next leaves almost nothing
            if after_next <= 2 {
                bonus += 40.0;
            }
            score -= bonus;
        } else {
            // next item won't fit: penalize wasted large residuals
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.3 * overshoot + 0.2 * (bin_residual as f64 - mean_residual).abs();
        }
    }

    // Dead-space penalty: graded; small residuals are worse
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 - 3.0 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Tighter bins preferred relative to mean residual
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= post_residual.max(1) && progress > 0.7 {
            new_bin_score -= 40.0 * progress;
        }
        // avoid opening new bins when plenty of open bins already fit
        if fitting_bins_count > 2 {
            new_bin_score += 20.0;
        }
        // when many bins are open and residual fragmentation is high,
        // consolidating into existing bins is preferable
        if open_bins_count > 20 && mean_residual > bin_capacity as f64 * 0.4 {
            new_bin_score += 15.0;
        }
        score += new_bin_score;
    }

    // Prefer filling bins with larger residual gaps when few bins fit the item
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 {
            score -= 40.0 * (fill_ratio - 0.8);
        }
        // extra reward for leaving residual exactly matching a common small item
        if post_residual >= 1 && post_residual <= 6 {
            score -= 12.0;
        }
    }

    // mildly favor bins whose residual is close to the item (tight fit)
    if bin_residual < bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * progress * 2.0 - progress * 0.5);

    // Penalize exact-fit waste asymmetry: small residuals are dead space late in stream
    let dead = (norm_pr * norm_pr) * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can fit the next item
    let next_fit = if next_item_size > 0 && post_residual >= next_item_size {
        -1.5 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        0.5 * (next_item_size as f64 / cap)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -3.0
    } else {
        0.0
    };

    // Mild penalty for spreading across too many open bins
    let spread = open_bins_count as f64 * 0.02;

    // Prefer bins below mean residual (tighter packing)
    let mean_pull = (mean_residual - pr) * 0.01;

    let score = poly + dead + next_fit + last_chance + spread + mean_pull;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large post residuals proportionally (wasted space).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is a dead gap for the known next item.
        score += 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score = bin_capacity as f64 + pressure * 8.0
            + if post_residual < 10 { 60.0 } else { 0.0 }
            - if open_bins_count == 0 { 100.0 } else { 0.0 };
    }

    // Progression: slightly tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

