        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fits post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tightness = (post_residual - next_item_size) as f64;
            score -= 100.0 - 0.5 * tightness;
        } else {
            // next item won't fit here: penalize large post_residuals that waste space
            score += 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize creating small unusable dead space (< 10 typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight preference for tighter bins relative to mean residual
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Early in stream, mildly discourage opening many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fits snugly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space (hard to reuse) more than large leftover space.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 3.0;
        }
        // Bonus for leaving a residual that plausibly matches typical small items.
        if pr >= 10.0 && pr <= 30.0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt as u32) <= post_residual {
            let reuse = nxt / pr_f64(post_residual);
            score -= 12.0 * reuse;
        } else {
            // Next item won't fit here: mild penalty scaled by how much we waste.
            score += 4.0 * (1.0 - fit_ratio);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing residuals are fragmented and many bins are open.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 20.0 * (1.0 - fragmentation) + 10.0 * progress;
        // But if the item is large relative to capacity, avoid hoarding new bins.
        if item_size as f64 > 0.7 * cap {
            score += 15.0;
        }
    } else {
        // Reward using existing bins more when many are open (consolidation pressure).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Global balance: prefer bins whose residual is below the mean (fill the fullest bins).
    score += ((bin_residual as f64 - mean_residual) / cap) * 5.0;

    // Time horizon: early in stream, be conservative (favor exact fits); late, fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;

    score
}

#[inline]
fn pr_f64(x: u32) -> f64 { (x.max(1)) as f64 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post * (1.0 + 0.6 * progress);

    // smooth polynomial coupling of post-residual with stream progress
    score += 30.0 * norm_post * norm_post * (0.5 + 0.5 * progress);

    // reward tight fits: penalize large wasted fraction quadratically
    score -= 25.0 * norm_item * (1.0 - norm_post) * (1.0 - norm_post);

    // lookahead coupling: favor bins whose post-residual matches next item smoothly
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs() / cap;
        score += 18.0 * gap * gap;
        score -= 8.0 * (1.0 - gap) * norm_next * (1.0 - norm_post);
    }

    // last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - norm_post);
    }

    // penalize bins far from mean residual (smooth dispersion term)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues are "dead space" -> penalize heavily.
    let dead = post_residual % 10;
    score += (dead as f64) * 1.5;

    // Perfect fit reward: post_residual exactly 0 or a multiple of 10 is reusable.
    if post_residual == 0 {
        score -= 60.0;
    } else if dead == 0 {
        score -= 25.0;
    }

    // Integer-division thresholds: post_residual classes.
    // post_residual in 1..=9 -> nearly dead; 10..=19 -> fits tiny items only, etc.
    let class = post_residual / 10;
    match class {
        0 => score += 40.0,           // 1..=9: almost unusable
        1 => score += 15.0,           // 10..=19: fits only small items
        2 => score += 5.0,            // 20..=29
        3 => score -= 5.0,            // 30..=39
        _ => score -= 10.0,           // >=40: very reusable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // Harmonic bonus: next item leaves a clean multiple-of-10 residue.
            if slack % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize more if this bin is the only option.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when item is large and
    // residual space left after placement is a clean class.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        if item_size > 50 {
            score -= 35.0; // large items are fine in fresh bins
        }
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 12.0; // next item won't fit the residue anyway
        }
    }

    // Slight preference for tighter bins as stream progresses (first-fit flavor).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (item sizes >= 1), so punish them far more than proportional residual.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // dead zone: 1..=10
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0; // soft dead zone
        } else if post_residual >= 50 {
            // Large leftover is reusable; reward keeping big residual space.
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 80.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins early,
    // but relax pressure as the stream progresses (end-game spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post residual, this placement
    // sets up a chain - reward it. If next item cannot use the leftover, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mean-residual coupling: placing into a bin with residual far below the
    // mean wastes the mean's potential; prefer bins near/below mean residual
    // only when the fit is good (fit_ratio already handles quality).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin is a fresh, fully reusable
    // resource. Prefer it over leaving large dead space, but only when the
    // best existing fit would be poor (score already reflects that).
    if bin_residual == bin_capacity {
        // Slight preference for new bins when many open bins are fragmented.
        score -= 5.0 + 0.1 * mean_residual;
        // But discourage opening new bins when few bins are open.
        if open_bins_count < 3 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item fits snugly
    // into the post_residual of this bin (chained placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Reward tight chaining: exact fit gets the biggest bonus.
        let tightness = 1.0 - (slack_after_next as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness + 6.0;
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize dead space
        // that is smaller than the next item (wasted gap).
        if post_residual < next_item_size {
            let gap_ratio = (post_residual as f64) / (next_item_size as f64);
            score += 8.0 * gap_ratio;
        }
    }

    // Relative residual positioning: bins with residual near the item size
    // are precious; leaving them even tighter is good.
    let mean_res = mean_residual.max(1.0);
    if (post_residual as f64) < mean_res {
        score -= 4.0 * (1.0 - (post_residual as f64) / mean_res);
    } else {
        score += 2.0 * ((post_residual as f64) / mean_res - 1.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bins are badly
    // fragmented. An empty bin gets a moderate penalty so we prefer packing.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_res / bin_capacity as f64).min(1.0);
        // Open a new bin only late in the stream or when open bins are very tight.
        score += 10.0 + 20.0 * fragmentation - 8.0 * progress;
        if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
            score -= 5.0; // no open bin helps the next item either
        }
    }

    // Mild preference for tighter fits overall (best-fit flavor).
    score -= (item_size as f64) / (bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward tight packing heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Penalize dead space relative to the smallest plausible future item.
    // Waste that can never be filled is worse than waste that might be.
    let min_future = 1u32;
    if post_residual > 0 && post_residual < min_future {
        score += 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly; reward it strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves further residual: mild reward, scaled
            // by how much room remains for a third item.
            score -= 20.0 * (post_residual as f64 - next_item_size as f64).min(50.0) / 50.0;
        } else {
            // Next item cannot use this bin's remainder: penalize the orphaned space,
            // worse when the gap is small (nearly-dead space).
            let gap = post_residual as f64;
            score += 10.0 + 30.0 * (1.0 - gap / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins that are already quite full
        // (best-fit style) via the base post_residual, but add a mild
        // penalty for spreading across too many open bins.
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    // Global state: compare this bin's residual to the mean residual.
    // Placing into a below-average-residual bin (fuller than average)
    // concentrates waste into fewer bins; reward that.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit flexibility); late in the stream, pack tightly
    // into existing bins to avoid leaving many half-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Late stream: penalize new-bin usage implicitly by boosting existing-bin preference.
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    // Early stream: slight penalty for near-empty-bin placements to keep flexibility.
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw post_residual (= capacity - item_size) is usually large, which
    // naturally deprioritizes it. Add explicit penalty unless nothing fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if the item is large relative
        // to capacity or late in the stream when tight packing matters.
        score += 40.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste term: dead space quadratic in small residuals
    let post_norm = post / cap;
    score += 6.0 * post_norm * post_norm * cap * (1.0 - post_norm);

    // Tight-fit reward (smooth, non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio) * cap * 0.25;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: penalize if next item fits better elsewhere / reward if it fits here
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 4.0 * (nx / post);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Stream-progress coupling: later in stream, prefer filling existing bins tighter
    score *= 1.0 - 0.25 * progress * (post_norm);

    // Slight penalty when many bins open (encourage consolidation)
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when fit elsewhere is bad
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize leftovers in "dead zones": (0,10) and (11..=19) are hard-to-fill slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // worst dead space
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // Reward exact / near-perfect packing (mod-10 harmonic classes).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // clean class, likely reusable by future items
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * fill;
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a big item
    // and open bins have fragmented residuals.
    if bin_residual == bin_capacity {
        // new bin: baseline score = capacity - item, plus fragmentation pressure
        score = (bin_capacity - item_size) as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        // open a new bin when existing mean residual is small relative to item
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0 + 20.0 * fragmentation;
        } else {
            score += 8.0 * fragmentation + 5.0 * progress;
        }
        // big items start fresh bins more readily
        if item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // favor tighter fits among open bins: reward small post_residual relative to bin
        score -= 5.0 * (1.0 - post_frac);
        // many open bins -> prefer consolidation
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 range, but treat < 12 as near-dead) are toxic.
    if post_residual < 12 {
        score -= 40.0; // perfect or near-perfect closure is excellent
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        // gap unusable by the immediate successor: heavy penalty
        score += 25.0;
    } else if post_residual < 20 {
        // small gap that only tiny items could use
        score += 10.0;
    }

    // Reward tight fits relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // opening a new bin (residual == capacity) should be penalized more.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (consolidating emptier bins
    // keeps fatter bins free for big items)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 12.0 {
            score -= 20.0;
        }
    }

    // Late in stream, be greedier about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item can chain into this bin: reward tight chain
            score -= 60.0 * (1.0 - gap / (bin_capacity as f64)) - 0.3 * gap;
        } else {
            // next item cannot fit: penalize dead space proportionally
            score += 0.5 * gap;
        }
        // exact chain match is ideal
        if gap == 0.0 {
            score -= 300.0;
        }
    } else {
        // last item: minimize leftover as much as possible
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin opening unless current open bins are nearly full
    if bin_residual == bin_capacity {
