}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post-residual and square it so small leftovers dominate.
    let post_frac = post_residual as f64 / cap;
    score += post_frac * post_frac * 40.0;

    // Penalize opening a new bin when existing bins fit, unless the fit is terrible.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        let mean_r = mean_residual;
        // If open bins have plenty of room on average, discourage new bin.
        score += 55.0 * (1.0 - tightness) * (1.0 - mean_r / cap).clamp(0.0, 1.0);
        // Late in the stream, new bins are cheap only if few bins are open.
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    } else {
        score -= 8.0; // slight bonus for reusing an existing bin
    }

    // Last-chance bin: strongly favor using it, especially if fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        score -= 35.0;
        score += waste * 0.25; // but not if it creates huge dead space
    }

    // Lookahead: penalize if the next item cannot fit in the post-residual,
    // but only when the current fit is not already tight.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
