    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let pressure = (mean_residual / cap) * (open_bins_count as f64).ln_1p();
    if bin_residual != bin_capacity {
        score -= pressure * 6.0;
    }

    // Discourage leaving residuals in the awkward 30-50 zone (hard to fill later).
    if post_residual >= 30 && post_residual <= 50 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 40.0 * poly * (1.0 + progress);

