        2 => score -= 1.0,   // 20..29
        3 => score += 2.0,   // 30..39
        4 => score -= 2.0,   // 40..49
        5 => score -= 3.0,   // 50..59
        6 => score -= 2.0,   // 60..69
        7 => score += 1.0,   // 70..79
        _ => {}
    }

