    // Prefer filling bins with larger residual gaps when few bins fit the item
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 {
            score -= 40.0 * (fill_ratio - 0.8);
        }
    }

    score
}

