pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much more
    // than proportionally. Anything below ~10 is nearly guaranteed dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }
    // Penalize residuals that are too small to fit even the smallest future item (1..100 range),
    // but not small enough to be caught above (conservative extra band).
    if post_residual > 0 && post_residual < 4 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another;
    // new empty bin gets penalized so consolidation is preferred.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    }

    // Lookahead: if next item could exactly fill the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item fits in post residual, mild reward; else mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // Progress-aware dead-space scaling: later in the stream, dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (filling the emptier-of-space bins first keeps big gaps available).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mildly penalize opening a bin unless current bins have bad fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count <= 1 { -30.0 } else { 12.0 };
        score += 25.0 + pressure;
        return score;
    }

    // 2-step lookahead: perfect chaining (post_residual == next_item_size) is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 45.0; // exact 2-step match: bin becomes perfectly full after next item
        } else {
            // penalize gap scaled by how close we are to a perfect chain
            score += gap * 0.35;
            // bonus if next item still fits (chainable)
            if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                // next item can't follow: dead space risk
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    } else {
        // Last item: minimize post residual directly (already the base).
    }

    // Penalize creating small unusable dead space relative to mean residual.
    if post_residual > 0 {
        let mean = if mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
        let rel = post_residual as f64 / mean;
        if rel < 0.5 {
            score += (0.5 - rel) * 20.0; // tiny slivers are wasteful unless perfectly chained
        }
    } else {
        score -= 30.0; // bin exactly filled: excellent
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer fuller bins slightly (tighter packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Penalize dead space: post residual that cannot hold typical future items
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 30.0 * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // penalize leaving a gap just below the next item size (unusable sliver)
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            if gap < 10 {
                score += 12.0;
            }
        }
    }

    // Global state coupling: prefer bins with residual below mean (consolidate large holes)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow new bins more readily since waste matters less per item
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late; also cheaper when many bins open
        let new_bin_bias = 55.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score += new_bin_bias;
        // allow new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // existing bins get slight preference as stream matures
        score -= 5.0 * progress;
    }

    // Fragmentation pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste shaping: penalize residuals that are too small to be useful
    let norm_post = post / cap; // in [0,1]
    let dead_zone = (1.0 - norm_post).powi(6); // grows sharply as residual shrinks
    score += dead_zone * cap * 0.35;

    // Smooth cubic coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (fewer chances to recover)
    let tightness = (norm_post * (1.0 - norm_post) * 4.0).powi(2); // peaks at residual = cap/2
    score -= tightness * cap * (0.10 + 0.25 * progress);

    // Lookahead: reward bins whose post_residual accommodates the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack).powi(2) * cap * 0.30 * (0.5 + 0.5 * progress);
        } else {
            let gap = (nxt - post) / cap;
            score += gap.powi(2) * cap * 0.20;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.25 * (0.3 + 0.7 * progress);
    }

    // Mild preference toward consolidating into fuller bins as open-bin count grows
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score -= (bin_residual as f64 / cap).powi(3) * cap * 0.15 * crowding;

    // Divergence from mean residual: prefer bins near the mean to keep options open
    let dev = (post - mean_residual) / cap;
    score += dev.abs().powi(2) * cap * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // ---- NEW BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        let mut s = cap * 0.6;
        // forced to open a bin: strongly favor
        if fitting_bins_count == 0 { s -= 60.0; }
        // large items are hard to place later: favor fresh bin
        if item_size as f64 > cap * 0.6 { s -= 15.0; }
        // leftover after placement can host the next item
        if nxt > 0.0 && post >= nxt { s -= 8.0; }
        // early in stream: be generous opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        s -= (1.0 - progress) * 10.0;
        return s;
    }

    // ---- EXISTING BIN SCORING ----
    let mut score = post;

    // dead-space penalty: unusable fragment below minimum item size
    if post < 10.0 {
        score += 30.0 + (10.0 - post) * 2.0;
    }

    // harmonic class of post_residual (buckets of 10): prefer classes that
    // align with typical item sizes; class 0 (perfect fit) best
    let cls = (post_residual / 10) as f64;
    score += cls * 1.5;

    // lookahead coupling: reward residuals that can host next item,
    // penalize residuals just barely too small (blocking)
    if nxt > 0.0 {
        if post_residual as f64 >= nxt {
            score -= 10.0;
        } else if nxt - post < 10.0 {
            score += 12.0; // near-miss: worst case dead space
        } else {
            score += 5.0;
        }
        // exact match bonus: next item fills this bin perfectly
        if post_residual as f64 == nxt { score -= 15.0; }
    }

    // last chance before opening a new bin: use it
    if fitting_bins_count == 1 { score -= 14.0; }
    // crowding: prefer bins among many fitting options less
    if fitting_bins_count > 2 { score += 2.0; }

    // prefer fuller bins (less cumulative waste)
    let used = (bin_capacity - bin_residual) as f64;
    score -= used * 0.12;

    // mean-residual coupling: if this bin is much emptier than average,
    // it is a better host
    score -= (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
