pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: tiny leftovers are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 8 {
            score += 70.0 * (9.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 2.5 * (21.0 - post_residual as f64);
        } else if post_residual >= 50 {
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 950.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure, relaxed as the stream progresses.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin early on.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 * (1.0 - progress);
    }

    // Lookahead: chain placement rewards, borrowed tightness shaping.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 150.0 - 0.75 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 9 {
                bonus += 70.0;
                if after_next <= 3 {
                    bonus += 30.0;
                }
            } else if after_next >= 9 && after_next < 20 {
                bonus -= 8.0;
            } else if after_next >= 20 && after_next <= 35 {
                bonus += 12.0;
            }
            if next_item_size > bin_capacity / 2 {
                bonus += 30.0;
            }
            if fitting_bins_count <= 2 {
                bonus += 46.0;
            }
            if after_next > 0 && after_next < item_size {
                bonus -= 20.0;
            }
            if after_next > 0 && after_next < next_item_size / 4 {
                bonus += 14.0;
            }
            if after_next == 0 {
                bonus += 25.0;
            }
            score -= bonus;
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.38 * overshoot + 0.28 * (bin_residual as f64 - mean_residual).abs();
