    // Near-miss shaping: residual just above next item.
    if post_residual >= next_item_size && post_residual <= next_item_size + 12 {
        score -= 15.0;
    }

    // Large open space with small item: mild reward.
    if bin_residual > 3 * bin_capacity / 4 && item_size < bin_residual / 2 {
        score -= 14.0;
    }

    // Mean-residual coupling with dead-space shaping.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;
    let dead_ratio = 1.0 - post_residual as f64 / cap;
    score -= 28.0 * progress * dead_ratio;
    score -= 6.0 * (1.0 - progress) * dead_ratio * dead_ratio;

    // Trapped residual: leftover smaller than next item is dead space.
    if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // New-bin candidate: open a fresh bin only when scarcity or a large
    // next item makes poor fits costly; penalize more as stream progresses.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 {
            125.0
        } else if fitting_bins_count == 2 {
            40.0
        } else {
            0.0
        };
        let big_next = if next_item_size > bin_capacity / 2 {
            60.0
        } else {
            0.0
        };
        let many_open = if open_bins_count > 12 { 12.0 } else { 0.0 };
