    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new empty bin unless current bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 40.0 - 30.0 * mean_tightness;
        // Later in the stream, be more willing to consolidate into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins tighter than the mean residual.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

