pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    let dead = (post_residual as f64) / bin_capacity as f64;
    if dead > 0.0 && dead < 0.10 {
        score += 15.0 * (0.10 - dead);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many options: be pickier, penalize mediocre fits.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0) * (1.0 - fit_ratio);
    }

    // New-bin candidate logic: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - (bin_capacity as f64 - item_size as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        // Prefer new bin when existing residuals are fragmented (low mean residual)
        score += 10.0 + mean_residual * 0.3 - pressure * 2.0;
        if avg_waste < 0.0 {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    } else {
        // Slight preference for filling bins that are already mostly full.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 6.0 * used;
    }

    // Global balance: if mean residual is high, tolerate looser fits; if low, be frugal.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Small time-horizon shaping: encourage efficiency as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * progress * 2.0 - progress * 0.5);

    // Penalize exact-fit waste asymmetry: small residuals are dead space late in stream
    let dead = (norm_pr * norm_pr) * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can fit the next item
    let next_fit = if next_item_size > 0 && post_residual >= next_item_size {
        -1.5 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        0.5 * (next_item_size as f64 / cap)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -3.0
    } else {
        0.0
    };

    // Mild penalty for spreading across too many open bins
    let spread = open_bins_count as f64 * 0.02;

    // Prefer bins below mean residual (tighter packing)
    let mean_pull = (mean_residual - pr) * 0.01;

    let score = poly + dead + next_fit + last_chance + spread + mean_pull;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bins whose post_residual lies in "dead" residue classes
    // (small leftovers that nothing can use) are penalized via modulo arithmetic.
    let r = post_residual;
    let dead_penalty = match r {
        0 => -30.0, // perfect fit
        1..=9 => 25.0, // tiny dead space, nearly unusable
        _ => {
            // residue classes modulo 10: leftovers like 10..19 are gold (small items fit)
            let cls = r % 10;
            match cls {
                0 => -8.0, // round residual: reusable by decade-sized items
                5 => -4.0, // half-decade also useful
                _ => (cls as f64) * 0.8, // odd residues mildly penalized
            }
        }
    };
    score += dead_penalty;

    // Integer-division thresholds: how many "typical small items" (size 10) fit after placement
    let slots = (r / 10) as f64;
    score -= slots * 2.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // harmonic class of next item vs residual: reward compatible residues
            let gap = r - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0;
            } else if gap < 10 {
                score += 10.0; // leaves dead space for the known next item
            } else {
                score -= (gap as f64).ln() * 3.0;
            }
        } else {
            // next item won't fit here; residual should ideally be small or highly reusable
            score += if r >= 10 { 0.0 } else { 15.0 };
        }
    } else {
        // last item: prefer zero residual strongly
        score += (r as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it only wins
    // when open bins have terrible fits.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0;
    } else {
        // prefer tighter bins (small residual before placement) among open bins
        score += (bin_residual as f64) * 0.15;
        // discourage scattering across many bins when mean residual is high
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Progress factor: later in the stream, be greedier about perfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100 - r.min(100)) as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large post residuals proportionally (wasted space).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
