    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + pressure * 25.0;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Prefer bins below mean residual (tighter bins) to consolidate waste
    score += (bin_residual as f64 - mean_residual) * 0.12;

    // Slight late-stream conservatism: avoid fragmenting bins near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

