    // A gap is "dead" if it's smaller than the minimum plausible item size.
    let min_item = if item_size < 10 { 1u32 } else { 10u32 };
    if post_residual > 0 && post_residual < min_item {
        score += 500.0 + (min_item - post_residual) as f64 * 10.0;
