    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 150.0 + pressure * 5.0;
        // If no open bin fits well (large dead-space risk), new bin is fine.
        if post_residual == bin_capacity - item_size && (bin_capacity - item_size) < min_item {
            score -= 400.0;
        }
    }

    // Open-bins pressure: mild penalty proportional to number of open bins
    // to discourage fragmenting across many bins when consolidation is possible.
    score += open_bins_count as f64 * 2.0;

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }

    // Progress: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * progress * 0.5;

