        }
    } else {
        // last item: minimize final residual hard
        score *= 2.0;
    }

    // Penalize dead space relative to the fleet mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item leaves a large awkward residual in every existing bin.
