        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0; // fresh bin chains perfectly
        } else {
            score += 25.0; // default: discourage opening new bins
        }
    }

    // Slight preference for tighter fits overall (non-linear in item size)
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

