pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space relative to capacity (non-linear)
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 120.0 * dead_frac * dead_frac;

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasting large residuals
            score += 30.0 * dead_frac;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation, penalize spreading
    if open_bins_count > 2 {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    // Global mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += 20.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early in stream, tolerate new bins; late in stream, prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; slight early bonus if item is large
        let mut new_bin_score = 250.0 + 350.0 * progress;
        if item_size > bin_capacity / 2 && progress < 0.3 {
            new_bin_score -= 60.0;
        }
        score += new_bin_score;
    } else {
        // Existing bin: reward more heavily late in the stream
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0;
        } else if post_residual >= 50 {
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 950.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure with progress relaxation.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0 * (1.0 - progress);
    }

    // Lookahead chain bonus: reward when next item exactly or nearly fills
    // the leftover; penalize unusable leftovers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 140.0 - 0.7 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 9 {
                bonus += 70.0;
                if after_next <= 3 {
                    bonus += 30.0;
                }
            } else if after_next >= 9 && after_next < 20 {
                bonus -= 8.0;
            } else if after_next >= 20 && after_next <= 35 {
                bonus += 12.0;
            }
            if next_item_size > bin_capacity / 2 {
                bonus += 30.0;
            }
            if fitting_bins_count <= 2 {
                bonus += 40.0;
            }
            if after_next > 0 && after_next < next_item_size / 4 {
                bonus += 14.0;
            }
            if after_next == 0 {
                bonus += 25.0;
            }
            score -= bonus;
        } else {
            // Next item cannot use leftover: penalize proportional waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.38 * overshoot + 0.28 * (bin_residual as f64 - mean_residual).abs();
            if overshoot < 6.0 {
                score += 22.0;
            }
        }
    }

    // Mean-residual coupling.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Dead-space pressure relative to mean, with chain relaxation.
    let dead = (post_residual as f64 - mean_residual).max(0.0);
    let chains = next_item_size > 0 && post_residual >= next_item_size;
    score += if chains { 0.22 } else { 0.6 } * dead;

    // Late-stage fill pressure: discourage leaving large unused capacity.
    let dead_ratio = 1.0 - post_residual as f64 / cap;
    score -= 28.0 * progress * dead_ratio;

    // New-bin candidate: open fresh bin only when scarcity or big next item
    // justifies it; discourage when many bins are open or late in stream.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 125.0 } else if fitting_bins_count == 2 { 40.0 } else { 0.0 };
        let big_next = if next_item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        let many_open = if open_bins_count > 12 { 12.0 } else { 0.0 };
        score -= scarcity + big_next + many_open;
        score += 24.0 * progress + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 45.0;
        }
    }

    // Nearly-chainable leftover: nudge toward fits that keep chains alive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize dead space that shrinks as stream progresses
    score += 0.4 * pr * pr / cap;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (cap - pr) as f64 * 0.2 * progress;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        if next_item_size as f64 > pr {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Encourage bins near mean residual to be used (smooth balancing)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure "wasted" dead space.
    let res_mod = post_residual % 10;
    score += (10 - res_mod) as f64 * 0.15; // prefer residuals landing on clean multiples of 10

    // Integer-division thresholds: residuals in [0..10) are nearly dead space -> strong penalty,
    // but a perfect fit (0) is ideal.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item's residue class complements the residual.
            let n_mod = next_item_size % 10;
            let r_mod = post_residual % 10;
            if n_mod == r_mod {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
            // Penalize leaving residual that is smaller than next item (dead space for lookahead)
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.4;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 20.0; // keep the single fitting bin attractive instead
        }
        // If mean residual across open bins is large, opening fresh is less costly.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    }

    // Tight-fit reward: item filling most of the bin is excellent.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 20.0;
    } else if fill > 0.7 {
        score -= 8.0;
    }

    // Late in the stream, consolidate: penalize spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 25.0;
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space),
    // but only mildly, since future items are uncertain.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // rather than spreading out; makes new bins less attractive.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it is genuinely needed, i.e. when
    // mean residual across open bins is small relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 - mean_residual).max(0.0);
        score += 40.0 + pressure;
    }

    // Mild preference for tighter fits overall: relative fill fraction.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score += diff * 1.5;                 // penalize mismatch with next item
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 40.0;                   // exact chain bonus
        }
        // post_residual that cannot fit next item is dead space until later
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: bins already tighter than average are good
    // targets (compact usage); loose bins above mean are penalized.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.6;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

