    score += 5.0 * mean_tight * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when open bins exist and can fit, scaled by stream length.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 10.0 * progress;
    }

    // Mild penalty for very large open-bin counts (fragmentation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks at mid residuals (dead-space penalty)
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 30.0 * progress);

    // Penalize leaving residual that cannot fit a typical next item (smooth coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward residual that smoothly matches the lookahead item.
        let match_term = 1.0 - ((pr - n) / cap).abs();
        score -= 8.0 * match_term.max(0.0) * match_term.max(0.0);
    }

    // Last-chance bonus: smooth function of fitting_bins_count.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        let f = fitting_bins_count as f64;
        score += 3.0 * (f - 1.0).ln() * (1.0 - progress);
