    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    let residue = post_residual % 10;
    // Residues 1..9 are hard to fill with items >=1 but typical items are larger;
    // treat small nonzero residues as penalized, residue 0 as rewarded.
    let residue_penalty = match residue {
        0 => -4.0,
        1 | 2 | 3 => 3.0,
        4 | 5 | 6 => 1.5,
        _ => 0.5,
    };
    score += residue_penalty;

    // Integer-division thresholds: post_residual bucketed by capacity fractions.
    let q = post_residual / (bin_capacity / 4); // 0..4 buckets
    score += match q {
        0 => -6.0,          // nearly full bin: excellent closure
        1 => 0.0,           // leftover ~25%: risky dead space
        2 => 2.0,           // ~50% leftover: mediocre
        _ => 4.0,           // mostly empty: wasteful unless new bin
    };

    // Coupling with next item (lookahead): if next item fits exactly into post_residual,
    // strongly reward; if next item cannot ever fit post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists or bin is fresh stream start.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score += 25.0 - pressure * 2.0 - progress * 5.0;
        // If current item nearly fills a fresh bin, opening is great.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // If next item is huge, fresh bin keeps flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Small bonus for exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

