pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // Dead space below the minimum item size is permanently wasted.
            score += 40.0 * (10.0 - pr);
        } else if pr < 20.0 {
            // Small gaps are unlikely to be filled by typical items.
            score += 12.0 * (20.0 - pr) / 10.0;
        } else if pr < 35.0 {
            score += 4.0 * (35.0 - pr) / 15.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt && pr - nxt < 10.0 {
            // Post-residual exactly accommodates next item with near-perfect fit.
            score -= 25.0;
        } else if pr < nxt && pr > 0.0 {
            // Gap cannot fit the next item: mild penalty scaled by wasted fraction.
            score += 8.0 * (1.0 - pr / nxt);
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, new bins are less desirable (less time to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // A new bin is more attractive if its residual (full capacity) can host the next item.
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 {
            score -= 5.0;
        }
    } else {
        // Filling existing bins is favored more when many bins are open.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr).min(30.0);
    }

    score
