pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }

    // Penalize residuals too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize creating tiny unusable residuals (below min item size ~1..100 range, use 10 as floor guess)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward using bins with below-average residual (tight bins) to keep large residuals open
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor filling it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0; // but allow if it sets up a perfect follow-up
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly in every open bin (i.e., no bin has a small post-residual).
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity.saturating_sub(item_size) as f64;
        let mut penalty = 55.0;
        // If lookahead item would fit nicely in the fresh residual, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            penalty -= 1.2 * pair_waste.max(0.0);
        }
        // Later in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 20.0 * progress;
        // Many open bins with slack -> opening new bins is less attractive.
        penalty += 3.0 * (open_bins_count as f64).ln().max(0.0);
        penalty -= 0.1 * mean_residual;
        score += penalty.max(0.0);
        score += 0.3 * waste_if_open;
    }

    // Lookahead synergy: reward placing item so next item also fits here.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let combined = (item_size + next_item_size) as f64;
            let slack = (bin_capacity as f64 - combined).max(0.0);
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize unusable sliver.
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.5 * (post_residual as f64).min(30.0);
            }
        }
    }

    // Prefer bins whose residual is close to mean residual (balanced usage),
    // but only mildly, so tight-fit logic dominates.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins when many bins are open.
    score -= 0.02 * (bin_capacity.saturating_sub(bin_residual)) as f64
        * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
