    score += (open_bins_count as f64).ln() * 2.0 * rn * rn;

    // Prefer bins with residual close to item (smooth fit term)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * fit_gap * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted after placement

    // Penalize residuals that fall into "unusable" harmonic bands.
    // Items are >= 1, so post_residual < 5 is essentially dead space.
    if post_residual < 5 {
        score -= 30.0; // perfect fill: excellent
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Integer division thresholds: which item classes could still fit?
        // Harmonic classes via modulo: residuals that are multiples of common
        // item sizes (e.g., divisible by 10 or 25) are more reusable.
        let harmonic_bonus = if post_residual % 10 == 0 {
            8.0
        } else if post_residual % 5 == 0 {
            4.0
        } else if post_residual % 25 == 0 {
            6.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
    }

    // Quadratic waste penalty scaled by capacity fraction (superlinear dead space cost)
    score += 40.0 * frac * frac;

    // Lookahead: if next item fits exactly in post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue; scale by fit tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * tight;
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // Neutral base: prefer existing bins with tight fits; empty bin scores
        // high (bad) unless its harmonic class is good for the item.
        score += 20.0;
        // If item is large relative to capacity, opening fresh is reasonable.
        if (item_size as f64) > 0.5 * cap {
            score -= 18.0;
        }
        // Early in stream, opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 6.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — reward filling it.
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= (dev / cap).min(0.5) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size historically ~10), so penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins; opening a new bin (residual == capacity) is penalized
    // proportionally to how many bins are already active.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a fresh bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement; if post_residual is slightly too small for the
    // next item, mild penalty (dead space from the next item's perspective).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < f64::EPSILON {
            score -= 30.0;
        } else if (post_residual as i64 - next_item_size as i64) < 0 && post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., already well-filled) to keep large residuals available.
    let my_residual = post_residual as f64;
    if my_residual < mean_residual {
        score -= 3.0 * (mean_residual - my_residual) / bin_capacity as f64;
    } else {
        score += 3.0 * (my_residual - mean_residual) / bin_capacity as f64;
    }

    // Late-stream tightening: as the stream progresses, be more aggressive
    // about avoiding new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: this bin becomes perfectly tight
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // residual left over after a hypothetical next-item placement
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - leftover.min(25.0); // small leftovers are great, large ones taper off
        } else {
            // next item cannot follow here: penalize proportional dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.35;
        }
        // if next item fits tightly relative to mean residual structure, nudge
        if next_item_size as f64 >= mean_residual {
            score += 3.0;
        }
    } else {
        // last item: just prefer tightest fit
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable slivers (dead space < min item size ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += pressure + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin pairs well with the upcoming larger item
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powf(4.0);

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: reward if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit here; slightly penalize hogging space.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let best_possible = if pressure > 0.0 { 0.0 } else {
            // estimate waste of forcing item into an open bin
            1.0
        };
        if pressure > 0.0 {
            score -= 60.0; // no open bin fits: open new bin
        } else {
            // competing against open bins: make new bin mildly unattractive
            score += 20.0 + 0.5 * open_bins_count as f64;
            let _ = best_possible;
        }
    }

    // Time horizon: early in the stream, be more willing to open bins / spread load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if bin_residual < bin_capacity {
        score -= 0.3 * mean_residual / open_bins_count.max(1) as f64;
    }

    // Prefer bins with residual close to item (ratio-based tightness).
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on post residual (waste), smoothed
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Non-linear coupling of post-residual with stream progress:
    // late in stream, tight fits matter more (dead space penalized harder)
    let progress_coupling = pr_norm * (1.0 - progress) * (progress * progress);
    score -= 30.0 * progress_coupling;

    // Reward near-perfect fits smoothly (small post residual relative to item)
    let tightness = (pr_norm.max(0.0)).powi(2) * (1.0 - fit_ratio);
    score -= 10.0 * tightness;

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Penalize opening new bins when open bins exist and fit reasonably
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 8.0 + 12.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        // If next item could use this bin's remaining space well, soften
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= pr {
                score -= 4.0 * (1.0 - nxt / cap);
            }
        }
    }

    // Lookahead synergy: reward bins whose post residual pairs with next item
    if next_item_size > 0 && !is_new_bin {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let pair_waste = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - pair_waste) * (1.0 - progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference toward bins below mean residual (consolidating small leftovers)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
