pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable (items are >= 1,
    // but gaps below the typical small-item size waste capacity).
    if post_residual < 10 {
        // Perfect or near-perfect fill: strongly reward.
        score -= 40.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 20 {
        // Small awkward gap: penalize extra.
        score += 12.0;
    }

    // Penalize gaps that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward exact fit of lookahead item (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if all open bins fit poorly (large dead space would result),
        // opening a new bin becomes relatively more attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0;
        }
    } else {
        // Mild reward for preferring tighter bins overall.
        score -= (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Progress-based tuning: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward exact/tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        // Tightness reward: smaller post_residual relative to capacity is better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness;

        // Lookahead: if the next item fits exactly into post_residual, huge reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 900.0; // chain closure: item + next fill bin exactly
            } else if next_item_size <= post_residual {
                // Next item fits: reward proportional to how well it fills remainder.
                let next_fill = next_item_size as f64 / post_residual as f64;
                score -= 120.0 * next_fill;
            } else {
                // Next item does NOT fit in post_residual: penalize dead space,
                // worse when post_residual is small but nonzero (unusable gap).
                let gap = post_residual as f64;
                let min_size = 1.0;
                let unusable = (gap / bin_capacity as f64).powf(1.5);
                // If next item is large, small gaps are more likely dead.
                let next_pressure = next_item_size as f64 / bin_capacity as f64;
                score += 60.0 * unusable * (0.5 + next_pressure);
                // Slight penalty if gap is below plausible minimum item size
                if gap < min_size {
                    score += 50.0;
                }
            }
        }
    }

    // Relative to mean residual: prefer bins whose post_residual diverges
    // favorably (smaller) from the mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 15.0 * ((mean_residual - post_f) / bin_capacity as f64);
    } else {
        score += 20.0 * ((post_f - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing fits are poor (large post_residual) or lookahead mismatch.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with number of open bins
        // to discourage bin proliferation, eases late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 80.0 + 3.0 * open_bins_count as f64 - 20.0 * progress;
        // If next item is huge, a fresh bin is valuable for it.
        if next_item_size >= 60 {
            new_bin_score -= 30.0;
        }
        // If the current item leaves a huge gap in any existing bin, fresh bin looks good.
        if post_residual > 50 {
            new_bin_score -= 25.0;
        }
        score = score.max(new_bin_score);
    }

    // Small tie-breaker: prefer fuller bins (lower residual before placement).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0;
        } else if post_residual >= 50 {
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 950.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure with progress relaxation.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0 * (1.0 - progress);
    }

    // Lookahead chain bonus: reward when next item exactly or nearly fills
    // the leftover; penalize unusable leftovers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 150.0 - 0.75 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 9 {
                bonus += 70.0;
                if after_next <= 3 {
                    bonus += 30.0;
                }
            } else if after_next >= 9 && after_next < 20 {
                bonus -= 8.0;
            } else if after_next >= 20 && after_next <= 35 {
                bonus += 12.0;
            }
            if next_item_size > bin_capacity / 2 {
                bonus += 30.0;
            }
            if fitting_bins_count <= 2 {
                bonus += 46.0;
            }
            if after_next > 0 && after_next < item_size {
                bonus -= 20.0;
            }
            if after_next > 0 && after_next < next_item_size / 4 {
                bonus += 14.0;
            }
            if after_next == 0 {
                bonus += 25.0;
            }
            if after_next > 0 && after_next < 40 && (after_next as f64) < 0.06 * cap {
                bonus += 10.0;
            }
            if after_next > 0 && (after_next as f64) > 0.5 * cap && next_item_size <= bin_capacity / 2 {
                bonus += 18.0;
            }
            score -= bonus;
        } else {
            // Next item cannot use leftover: penalize proportional waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.38 * overshoot + 0.28 * (bin_residual as f64 - mean_residual).abs();
            if overshoot < 6.0 {
                score += 22.0;
            }
        }
    }

    // Mean-residual coupling.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Dead-space pressure relative to mean, with chain relaxation.
    let dead = (post_residual as f64 - mean_residual).max(0.0);
    let chains = next_item_size > 0 && post_residual >= next_item_size;
    score += if chains { 0.22 } else { 0.6 } * dead;

    // Late-stage fill pressure: discourage leaving large unused capacity.
    let dead_ratio = 1.0 - post_residual as f64 / cap;
    score -= 28.0 * progress * dead_ratio;

    // Large-bin late fill: prefer placing small items into spacious bins.
    if bin_residual > 3 * bin_capacity / 4 && item_size < bin_residual / 2 {
        score -= 14.0;
    }

    // New-bin candidate: open fresh bin only when scarcity or big next item
    // justifies it; discourage when many bins are open or late in stream.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 125.0 } else if fitting_bins_count == 2 { 40.0 } else { 0.0 };
        let big_next = if next_item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        let many_open = if open_bins_count > 12 { 12.0 } else { 0.0 };
        score -= scarcity + big_next + many_open;
        score += 24.0 * progress + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 45.0;
        }
    }

    // Small item into near-doomed residual: discourage early, allow late.
    if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // Nearly-chainable leftover: nudge toward fits that keep chains alive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
        score -= 10.0;
    }

    score
}

