    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Waste if post_residual can't fit the next item.
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, prefer closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * 10.0;

    // Global state: many open bins -> prefer filling existing ones;
    // few open bins -> opening a new bin is less costly.
    let open_bonus = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but discount when few bins open
        // or when this bin would leave a very tight fit elsewhere.
        score += 15.0 + open_bonus * 2.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    } else {
        score -= open_bonus * 0.5;
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // it is relatively full already; prefer it.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    score
}

