pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = 2.0 * poly * cap;

    // Reward tight fits, stronger later in the stream
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (20.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.8 + 1.2 * progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(4.0) * (1.0 + 2.0 * progress);
    }

    // Coupling with mean residual: prefer bins deviating from the mean
    let dev = (pr as f64 - mean_residual) / cap;
    score -= dev * (5.0 + 10.0 * progress);

    // New-bin candidate: prefer it only when residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).min(1.0);
        let new_bin_score = 0.35 * cap + 0.4 * cap * frag * frag * (1.0 - progress)
            + (open_bins_count as f64) * 0.5;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter/third of the bin it lands in.
    let post = post_residual as f64;
    let quarter = post_residual / (bin_capacity / 4);
    let third = post_residual / (bin_capacity / 3);
    let parity = post_residual & 1;

    // Dead-space penalty: residuals that no plausible item (1..=100) can fill well.
    // Post-residual in (0, 10) is nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Post-residual in the "awkward band" 10..=25 is hard to fill with typical items.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Small harmonically-useful leftovers (25, 50, 75) are valuable slots.
    if post_residual == 25 || post_residual == 50 || post_residual == 75 {
        score -= 25.0;
    }
    if post_residual == 10 || post_residual == 20 {
        score -= 8.0;
    }

    // Modulo-class coupling: does post_residual + next_item_size land on a nice boundary?
    if next_item_size > 0 {
        let combo = post_residual + next_item_size;
        if combo <= bin_residual {
            // next item still fits after this placement -> mild reward
            score -= 6.0;
            if combo % 10 == 0 {
                score -= 10.0; // lands on a decade boundary: excellent packing
            }
        } else {
            score += 8.0;
        }
        // Next item is huge; prefer bins where it fits afterward.
        if next_item_size >= 50 && combo <= bin_residual {
            score -= 10.0;
        }
        // Harmonic pairing: post_residual + next_item_size == capacity exactly.
        if combo == bin_capacity {
            score -= 45.0;
        }
    } else {
        // Last item: just minimize waste.
        score = post as f64 * 2.0;
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 30 {
            score -= 15.0;
        }
    }

    // New-bin candidate: baseline score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // If the current item nearly fills a fresh bin, a new bin is reasonable.
        if item_size >= 70 {
            score -= 20.0;
        }
        // If next item is large and this bin would leave a big residual, new bin ok.
        if next_item_size >= 60 && item_size >= 50 {
            score -= 12.0;
        }
    }

    // Mild preference for tighter bins when residuals are large overall.
    score += (mean_residual - post) * 0.05;

    // Quarter-class tiebreak: prefer leaving residuals in the upper half (more usable).
    match quarter {
        0 => score += 5.0,   // post < 25: poor leftover
        1 => score += 0.0,   // 25..50
        2 => score -= 3.0,   // 50..75
        _ => score -= 5.0,   // >= 75: very usable leftover
    }
    let _ = third;
    let _ = parity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward residuals that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing
    // bins over spreading items; when few bins are open, opening new ones is
    // relatively cheap.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * 3.0;

    // Tight fits (small post_residual relative to item) are desirable.
    score -= (item_size as f64) * 0.3;

    // Early in the stream, opening fresh bins is more acceptable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Slightly prefer bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        if item_size > 50 && post_residual >= 10 {
            score -= 5.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with slight superlinear pressure on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward when post_residual exactly accommodates next item,
    // penalize dead space that next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            // exact match is best; extra slack is mildly penalized
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            score += slack as f64 * 0.3;
        } else {
            // next item cannot follow into this bin -> dead space penalty
            score += (nxt - post) * 0.6;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when it enables a great 2-step chain,
    // otherwise discourage proliferation of open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64 - item_size as f64) >= 0.0 {
            score -= 15.0;
        }
    }

    // Contextual: compare against mean residual of open bins; prefer placing into
    // bins already below-average residual (consolidation).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, tighten up: minimize residual more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: strongly reward bins whose post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // residual that can still host the next item is valuable
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably well
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size ~1..small)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Prefer bins below mean residual (tighter packing) early, relax late
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_pull = (mean_residual - bin_residual as f64) * (1.5 - progress);
    score += mean_pull;

    // Encourage consolidating into fewer bins when many are open
    score += 0.1 * open_bins_count as f64;

    // Mild preference for fuller bins (small post_residual) as stream progresses
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when current residuals are poor
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        let desperation = (fitting_bins_count == 0) as i32 as f64 * 300.0;
        score = 250.0 + avg_fit * 200.0 - desperation;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 50.0; // big next item benefits from fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (1.0 - progress);

    // Prefer tight fits: reward small post_residual with a quadratic bonus
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0;

    // Penalize dead space late in the stream
    score += norm_pr * norm_pr * 30.0 * progress;

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mild preference toward bins deviating from mean residual (consolidation)
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    // New-bin candidate: keep it competitive only when it looks genuinely useful
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse capacity fractions. Small post_residual (<10) is "dead space"
    // in the classic harmonic sense -> penalize.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 8.0;
    } else if post_residual <= 35 {
        score += 2.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    } else {
        score -= 6.0; // large leftover, still reusable
    }

    // Integer-division harmonic classes: does the leftover match common
    // item-size bands (1..=10, 11..=25, ...)? Reward exact-class matches
    // with the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let class = |x: u32| x / 10; // harmonic bucket
            let match_bonus = if class(next_item_size) == class(post_residual) {
                12.0
            } else {
                5.0
            };
            score -= match_bonus;
            // extra reward if the NEXT item leaves a perfect or tiny residual too
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 15.0;
            } else if next_post < 10 {
                score += 10.0; // would create sliver after lookahead
            }
        } else {
            score += 6.0; // lookahead cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave bad slivers AND the item is large.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin anyway
        } else if post_residual < 20 && next_item_size > post_residual {
            score += 5.0; // discourage wasteful new bin
        } else {
            score += 15.0; // default: prefer existing bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Progress-scaled tightness reward: later in the stream, prefer
    // tighter fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual - post_residual) as f64 * (0.1 + 0.2 * progress);

    // Nudge toward bins whose residual is near the mean (keeps spread balanced).
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=9)
    // are pure waste; penalize them heavily, with a cliff at 10.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Usable gap: mild reward for tightness (small usable residual).
        score -= 0.3 * (100.0 - post_residual as f64) / 100.0;
    }

    // Reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it unattractive unless current bins are very full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 + 30.0 * mean_fill;
    }

    // Late-stream conservatism: as stream ends, avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0;
        } else if post_residual >= 50 {
            score -= 10.0 + 0.2 * (post_residual as f64 - 50.0);
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 950.0;
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure with progress relaxation.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0 * (1.0 - progress);
    }

    // Lookahead chain bonus: reward when next item exactly or nearly fills
    // the leftover; penalize unusable leftovers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 150.0 - 0.75 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
            if after_next > 0 && after_next < 9 {
                bonus += 70.0;
                if after_next <= 3 {
                    bonus += 30.0;
                }
            } else if after_next >= 9 && after_next < 20 {
                bonus -= 8.0;
            } else if after_next >= 20 && after_next <= 35 {
                bonus += 12.0;
            }
            if next_item_size > bin_capacity / 2 {
                bonus += 30.0;
            }
            if fitting_bins_count <= 2 {
                bonus += 46.0;
            }
            if after_next > 0 && after_next < item_size {
                bonus -= 20.0;
            }
            if after_next > 0 && after_next < next_item_size / 4 {
                bonus += 14.0;
            }
            if after_next == 0 {
                bonus += 25.0;
            }
            if after_next > 0 && after_next < 40 && (after_next as f64) < 0.06 * cap {
                bonus += 10.0;
            }
            if after_next > 0 && (after_next as f64) > 0.5 * cap && next_item_size <= bin_capacity / 2 {
                bonus += 18.0;
            }
            score -= bonus;
        } else {
            // Next item cannot use leftover: penalize proportional waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.38 * overshoot + 0.28 * (bin_residual as f64 - mean_residual).abs();
            if overshoot < 6.0 {
                score += 22.0;
            }
        }
    }

    // Mean-residual coupling.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Dead-space pressure relative to mean, with chain relaxation.
    let dead = (post_residual as f64 - mean_residual).max(0.0);
    let chains = next_item_size > 0 && post_residual >= next_item_size;
    score += if chains { 0.22 } else { 0.6 } * dead;

    // Late-stage fill pressure: discourage leaving large unused capacity.
    let dead_ratio = 1.0 - post_residual as f64 / cap;
    score -= 28.0 * progress * dead_ratio;

    // Large-bin deep-fill nudge: prefer placing small items into mostly-full bins.
    if bin_residual > 3 * bin_capacity / 4 && item_size < bin_residual / 2 {
        score -= 14.0;
    }

    // New-bin candidate: open fresh bin only when scarcity or big next item
    // justifies it; discourage when many bins are open or late in stream.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 125.0 } else if fitting_bins_count == 2 { 40.0 } else { 0.0 };
        let big_next = if next_item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        let many_open = if open_bins_count > 12 { 12.0 } else { 0.0 };
        score -= scarcity + big_next + many_open;
        score += 24.0 * progress + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 45.0;
        }
    }

    // Nearly-chainable leftover: nudge toward fits that keep chains alive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
        score -= 10.0;
    }

    // Stranded-residual penalty: leftover too small for the current item and
    // too small for the next one is likely dead space late in the stream.
    if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Strong reward for perfect chain (post_residual == next_item_size)
        if slack_after_next == 0 {
            score -= 60.0;
        } else {
            // Reward proportional to how well the chain packs
            score -= 40.0 * (1.0 - slack_after_next as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste.min(50.0);
    }

    // Penalize small unusable residuals relative to mean residual
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in stream: avoid opening new bins
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    } else {
        // Slight preference for fuller bins
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (best-fit core).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: penalize leaving a residual that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that are compatible with the next item,
            // scaled by how much of the residual the next item would consume.
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * use_ratio;
        } else {
            // Dead space penalty: next item can't use what's left.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowd penalty: with many open bins, prefer consolidating into
    // already-open bins rather than spreading out.
    let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
    score += open_frac * (post_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to benefit from good residual structure); late in the
    // stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        // New bin base cost: high, but discounted early and when no open bin fits well.
        let mut new_bin_cost = 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0; // must open a bin anyway
        }
        // Prefer opening a new bin when item is large relative to capacity.
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 10.0;
        score += new_bin_cost;
    } else {
        // Placing into an existing bin gets a small early-stream reward.
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if mean residual is high, reward bins that
    // reduce global fragmentation (i.e., consume more of their space).
    let mean_res_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_res_gap;

    // Absolute waste guard: never leave residuals below the minimum item
    // size that are unlikely to be filled — small dead space is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;

    // Base: prefer tight fits, with progress-dependent curvature
    let mut score = prn * (1.0 + 0.9 * progress * prn);

    // Non-linear coupling: waste penalized more as stream advances
    score += 0.35 * progress * prn * prn * (1.0 - prn);

    // Item-size interaction: large items should avoid leaving big residuals
    score -= 0.5 * irn * (1.0 - prn) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Prefer bins below mean residual (consolidate emptier bins)
    score += 0.25 * (mean_residual - pr) / cap;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nn = next_item_size as f64 / cap;
        let gap = prn - nn;
        if gap >= 0.0 {
            score -= 0.6 * gap * (1.0 - gap);
        } else {
            score += 0.4 * (-gap);
        }
    }

    // New-bin candidate: make it moderately attractive early, costly late
    if bin_residual == bin_capacity {
        score += 0.8 + 1.5 * progress * progress;
    }

    // Mild penalty for bin proliferation
    score += 0.02 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
