pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "small leftover" class are more valuable; large dead space is penalized.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Quadratic waste penalty (dead space is super-linearly bad).
    score += 40.0 * frac * frac;

    // Modulo-10 class of post_residual: residuals divisible by 10 align with
    // the common item-size grid (items 10..80), making leftovers reusable.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 6.0;
    } else {
        score += (rem10 as f64) * 0.8;
    }

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the leftover match the next item's size class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward leftovers that can still host the next item tightly.
            score -= 8.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 12.0; // chain of perfect fits
            }
            // Integer-division harmonic class: leftover can host >=2 next-items.
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 3.0;
            }
        } else {
            // Leftover too small for next item: dead space risk.
            score += 5.0 + 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin is
    // very full (small residual) or fits are scarce.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Early in the stream, opening bins is cheaper; later, fill existing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual context: if this bin is much emptier than average,
    // deprioritize dumping a large item into it (save it for big items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Item-size class reward: placing large items into tight bins is good.
    if item_size as f64 > 0.5 * cap {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, minimum item size) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately small gaps are risky dead space
        score += 18.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins,
    // penalize opening a new empty bin
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Prefer bins whose residual deviates below mean (tighter bins get used first)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits the post-residual, reward; if it nearly fits (small miss), penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 20.0;
        }
    }

    // Slight preference for tighter fits relative to bin residual
    score += (item_size as f64 / bin_residual as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact 2-step lookahead match: post_residual equals next_item_size -> chain fill
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 900.0;
        } else if post_residual as u32 > next_item_size {
            // next item still fits after this placement
            score -= 120.0 + 0.5 * (post_residual as f64 - next_item_size as f64).max(0.0);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 80.0 + 0.8 * (next_item_size as f64 - post_residual as f64);
        }
        // lookahead feasibility relative to mean residual
        if (next_item_size as f64) <= mean_residual {
            score -= 30.0;
        }
    } else {
        // last item: minimize leftover strongly
        score += 0.5 * (post_residual as f64);
    }

    // Tight fit reward relative to capacity
    score -= 0.3 * (item_size as f64 / cap) * 100.0;

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 200.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) >= post_residual as f64 {
            score += 50.0;
        }
    }

    // Small penalty for many open bins with high mean residual (fragmentation)
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (~1..10) is worthless.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 5.0; // perfect fit bonus
    }

    // Penalize creating dead space that likely can't be filled later.
    let waste_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < waste_threshold {
        score += (waste_threshold - post_residual as f64) * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 3.0;
        } else {
            // next item won't fit here; slight penalty if this bin becomes tiny
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Prefer bins whose residual is close to the item (relative fit).
    let rel_fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= rel_fit * 4.0;

    // Global state: when many bins are open, discourage opening new ones
    // (consolidate), i.e., penalize the new-bin candidate implicitly by
    // rewarding existing bins.
    score -= open_bins_count as f64 * 0.15;

    // Mean residual coupling: if this bin is far below mean residual
    // (already fragmented), penalize; if above mean, it's roomy, mild bonus.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Time horizon: early in stream, be slightly more willing to open new
    // bins (long future to fill them); late in stream, consolidate tightly.
    let new_bin_penalty = 10.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic penalty.
        score += 4.0 + new_bin_penalty;
    } else {
        score -= new_bin_penalty * 0.05;
    }

    // Small non-linear shaping of post_residual to break ties toward
    // moderate leftover space (usable for typical items).
    score += ((post_residual as f64) * (bin_capacity as f64 - post_residual as f64)).sqrt() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * pr * norm_pr * (1.0 - progress);

    // Smooth cubic interaction: penalize tiny residuals more as stream progresses.
    score += 12.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (0.5 + progress);

    // Reward tight fits (small post_residual) smoothly.
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (item_size as f64 / cap);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins whose residual deviates far below mean (fragmentation).
    score += 0.15 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let smooth = 1.0 / (1.0 + (-(pr - next_item_size as f64) / 10.0).exp());
        score -= 8.0 * smooth * fits_next + 4.0 * (smooth - 0.5).abs();
    }

    // Mild penalty for opening many bins late.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residual is nearly full capacity.
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * (1.0 - progress) - 15.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fraction classes)
    let cap10 = bin_capacity / 10;
    let post_class = post_residual % cap10;
    let post_quot = post_residual / cap10;

    // Reward post-residuals that fall in "usable" harmonic classes.
    // Classes near 0 (tight fit) are excellent; classes just above 0 leave slivers.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_class <= 2 {
        score -= 18.0; // near-perfect, tiny sliver
    } else if post_class >= cap10 - 3 {
        score -= 10.0; // large chunk remains, still reusable
    } else {
        score += (cap10 as f64 / 2.0 - post_class as f64).abs() * 0.8; // awkward middle slivers
    }

    // Penalize per full decade of wasted space beyond the first
    score += post_quot as f64 * 4.0;

    // Lookahead coupling: does next_item_size harmonically fit the post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size.min(bin_capacity);
        if nxt == 0 {
            // unreachable
        } else if nxt <= post_residual {
            let nxt_class = nxt % cap10;
