            score += 6.0 + (nxt - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates (post_residual already does this)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling: only open a new bin when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs()
        } else {
            0.0
        };
        // Base penalty so new bins are only chosen for large items or high fragmentation
        score += 55.0 - fragmentation * 0.6 - progress * 5.0;
