        if item_size >= bin_capacity / 4 * 3 {
            score -= 20.0;
        }
        if post_residual <= cap10 {
            score -= 25.0;
        }
    }

    // Mild global pressure: when many bins are open, tighten packing
    score += open_bins_count as f64 * 0.05 + mean_residual * 0.02;

    // Small harmonic tie-break on item class
    let item_class = item_size % cap10;
    if item_class == 0 {
        score -= 3.0; // round-number items pack predictably
    }

    score
}

