pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define a "dead zone": gaps too small to fit even the smallest plausible item (1..=10)
    // or gaps that can't fit the lookahead item.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Almost-dead gap: strong penalty proportional to how much capacity is wasted.
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead dead space),
    // but only mildly, so perfect fits still dominate.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward gaps that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as i64 - next_item_size as i64) as f64;
        if slack < 10.0 {
            score -= 15.0 - slack;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        if post_residual > 0 && post_residual < 20 {
            score += 25.0;
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones (favor low post_residual
    // even more); with few open bins, allow opening new bins for tight fits.
