    let pressure = (open_bins_count as f64 / 8.0).min(3.0) * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below mean, filling it is cheap.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= (dev / 20.0).min(8.0);
    }

    // New-bin candidate: only attractive when current item is small relative to capacity
    // and no open bin gives a tight fit (post_residual large).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // A fresh bin has post_residual = capacity - item; encourage it for large items,
        // discourage for small items (which should go into existing residual space).
        score += 30.0 * (1.0 - tightness);
        if open_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score += (post_residual as f64) * 0.5;

    // 2-step lookahead: exact match of next item into post_residual is excellent
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 18.0 - (leftover as f64) * 0.3;
        if leftover == 0 {
            score -= 25.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; dead-space penalty scaled by gap
        score += ((next_item_size - post_residual) as f64) * 0.25;
    }

    // Reward residuals close to mean_residual (keeps bin portfolio balanced)
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are poor,
    // but discount late in the stream when consolidation matters less
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    // Prefer filling bins that are already fairly full
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fullness * 8.0;

    // Penalize many open bins (encourage consolidation)
    score += (open_bins_count as f64) * 0.3;

    // Tiny waste penalty
    score += (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize leaving dead space too small for the smallest plausible item,
    // unless it is essentially zero (already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // dead space that the next item cannot use
            score += 15.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer it heavily
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is bad. Make the empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the stream is early and many bins are open with scattered
        // residuals, opening fresh bins is less harmful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If next item is huge, a fresh bin can serve it well.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Global fragmentation pressure: when mean residual across open bins is
    // low, be more eager to fill existing bins tightly rather than spreading.
    let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * frag * (1.0 - tightness);

    // Late-stream consolidation: toward the end, prefer bins that get closed out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    // Mild penalty on very large open-bin counts to discourage sprawl.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit: strongly rewarded.
    if post_residual == 0 {
        score -= 950.0;
    } else if post_residual <= 8 {
        // Tiny dead gaps are nearly unusable: penalize softly.
        score += 45.0 * (9.0 - post_residual as f64);
    } else if post_residual >= 55 {
        score -= 8.0 + 0.15 * (post_residual as f64 - 55.0);
    }

    // Reward tight fits relative to the item itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure with progress relaxation.
    score += (open_bins_count as f64).powf(1.3) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 * (1.0 - progress);
    }

    // Lookahead chain bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            let mut bonus = 150.0 - 0.75 * tightness;
            let after_next = post_residual.saturating_sub(next_item_size);
