    if post_residual > 0 && post_residual < item_size && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // Nearly-chainable leftover: nudge toward fits that keep chains alive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
        score -= 10.0;
    }

    // Two-step lookahead: if next item fills the leftover and the bin after that
    // would be nearly empty, this placement wastes less overall.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 && next_item_size as f64 > 0.8 * cap {
