    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more -> steeper penalty curve.
    let coupling = prn.powi(2) * (1.0 + 3.0 * progress) + prn.powi(3) * (2.0 * progress);
    score += coupling * 40.0;

