    if mod10 == 0 {
        score -= 12.0;
    } else if mod10 <= 3 || mod10 >= 7 {
        score += 6.0; // awkward sliver classes
    } else {
        score += 2.0;
    }

    // Integer division thresholds: classify post_residual into dead-space tiers
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual < 10 {
        score += 15.0; // unusable dead space below min item size
    } else if post_residual <= quarter {
        score += 4.0;
    } else if post_residual <= half {
        score -= 3.0;
    } else {
        score -= 6.0; // still roomy
    }

    // Coupling with next item (lookahead): reward residuals that fit next item's class
