        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 14.0; // next item closes harmonically
            } else {
                score -= (slack as f64) * 0.15;
            }
        } else {
            // next item won't fit here; penalize only mildly if residual is useful
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * pressure - 10.0 * progress;
    }

    // Mild preference for bins tighter than the mean (best-fit flavor)
    score += ((post - mean_residual) * 0.1).clamp(-8.0, 8.0);

    // Slight consolidation bonus when many bins are open
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

