        score += (usable_thresh - post_residual as f64) * 3.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residuals that exactly fit the lookahead item are also excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the dead space cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
