    // Slight preference for filling existing bins over opening new ones,
    // weakening as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is huge and nothing else works
        score += 20.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: prefer filling.
        score += 10.0 + 30.0 * progress;
        // If many open bins already, discourage more.
        score += 0.8 * open_bins_count as f64;
    }

    // Global residual pressure: if mean residual is large, prefer filling existing bins.
    let mean_tight = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.15 * mean_tight;

    // Mild preference for bins with residuals close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
