pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = x + 0.9 * x * x + 1.2 * x * x * x;

    // Tight fits (post_residual near 0) strongly rewarded
    let tightness = 1.0 - x;
    score -= 2.5 * tightness * tightness * tightness;

    // Exact fill bonus (smooth, via polynomial in post)
    score -= 3.0 * (1.0 - x.min(1.0)).powi(6);

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 1.5 + 1.5 * progress;
    }

    // Stream progress coupling: early on, prefer keeping residuals flexible;
    // late, prefer filling bins tightly. Smooth interaction with post_residual.
    score += 1.8 * (1.0 - progress) * x * (1.0 - x);
    score -= 1.2 * progress * (1.0 - x) * (1.0 - x);

    // Penalize bins far from mean residual (prefer balanced residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.6 * dev * dev;

    // Lookahead: if next item fits perfectly in post-residual, reward; if it cannot fit, penalize dead space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fit_gap = (post - nx) / cap;
            score -= 1.5 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 0.8 * ((nx - post) / cap);
        }
    }

    // Mild penalty for opening many bins relative to need
    score += 0.15 * open_bins_count as f64 / (total_items.max(1) as f64);

    score
}

