pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: if the next item fits perfectly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - next_fit_gap / bin_capacity as f64);
        // Extra reward for near-perfect two-item packing.
