        score += 0.5 * miss;
    }

    // Penalize dead space relative to the mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Small residuals are hard to use later: penalize very tight leftovers unless they fit next item.
