    // but encourage it when residual would be very fragmented.
    if bin_residual == bin_capacity {
        score = 100.0 - 0.1 * open_bins_count as f64;
        // Allow opening a new bin late in the stream when leftover would be tiny.
        if next_item_size > 0 && post_residual == bin_capacity - item_size && post_residual < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    score -= (bin_capacity - post_residual) as f64 * 0.9;

    // Penalize small post residuals only if they are truly dead space:
    // dead space = post_residual that cannot hold next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            score -= 3.0; // next item can chain here: good
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: penalize heavily unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) < 15;
        if !poor_fit && fitting_bins_count > 0 {
            score += 25.0 + open_bins_count as f64;
        } else if fitting_bins_count > 0 {
            score += 8.0; // still mildly discourage waste
        }
    }

    // Prefer bins whose residual is close to the mean (keep balance),
    // scaled by progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.05 + 0.10 * progress);

    // Late in the stream, consolidate: prefer fullest bins even more.
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * progress;

