pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p = progress;
    let coupling = norm_pr * (1.0 + 2.0 * p * p + 1.5 * p * norm_pr);

    let mut score = pr * (0.9 + 0.6 * p * p) + coupling * 8.0;

    // Penalize tight fits less as stream advances (dead space matters more late).
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + p);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 25.0 * p;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 10.0 * (1.0 - gap * gap);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
