        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals in "good" residue classes of capacity.
    // Residuals that are multiples of 25 (or small <=5) are highly reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr % 25 == 0 {
        score -= 30.0;
    } else if pr % 10 == 0 {
        score -= 15.0;
    } else {
        // dead space penalty grows for awkward residues (e.g. 13,17,19-ish primes)
        let awkward = (pr % 25) as f64;
        score += 0.6 * awkward;
    }

