    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - 0.3 * slack;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.25 * ((next_item_size - pr).min(40) as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins: deviation from mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early stream: encourage spreading (keep bins balanced) to preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64);
    } else {
