pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64).powi(2);

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Bonus if next item fits exactly after placement.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize if next item cannot fit in this bin afterwards (dead end).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual is far below mean (fragmented bins).
    score += 0.5 * (mean_residual - bin_residual as f64).abs() / (bin_capacity as f64);

    // Penalize opening a new bin when decent open bins exist (empty-bin candidate).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 30.0 * pressure + 5.0;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Small bonus for filling bins more than half full in one shot.
    if item_size as f64 > 0.5 * bin_capacity as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0; // small dead space is nearly a perfect fit
    }

    // Penalize creating residual that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // awkward sliver below minimum item size
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward if next item exactly fills remaining space
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // Global state coupling: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 5.0;
    }
    // Early in the stream, slightly favor opening new bins to build flexibility.
    if progress < 0.15 && bin_residual == bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin should be chosen only when
    // the fit into existing bins is poor. Penalize empty-bin candidate by
    // its full unused capacity, but discount when few fitting bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 * (fitting_bins_count as f64).recip().min(1.0);
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for filling bins that are already half-full or more.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 6.0;

