    // Reward filling a bin nearly exactly (small post residual), stronger with progress.
    let fill_bonus = (1.0 - tightness).powi(3);
    score -= fill_bonus * (20.0 + 30.0 * progress);

    // Lookahead: penalize if next item cannot fit the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // reward leaving room exactly usable by the next item
            let gap = (pr - nxt) / cap;
            score -= (1.0 - gap) * 12.0;
        } else {
            score += (nxt - pr) * (0.3 + 0.5 * progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // More open bins -> mild pressure to consolidate into existing bins.
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins close to the mean (balanced usage),
    // with a smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: only attractive when residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let open_penalty = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
        score += 8.0 - fragmentation * 25.0 + open_penalty * 10.0 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions (dead-space severity classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;   // 25
    let fifth = bin_capacity / 5;     // 20
    let tenth = bin_capacity / 10;    // 10

    // Reward tight fits: leftover in the smallest harmonic classes is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= tenth {
        score -= 40.0; // nearly full bin
    } else if post_residual <= fifth {
        score -= 20.0;
    } else if post_residual <= quarter {
        score -= 5.0;
    } else {
        // Large leftover: penalize dead space, scaled by how unusable it is.
        score += (pr - quarter as f64) * 0.15;
    }

    // Harmonic coupling with the next item: reward leftovers that the
    // next item can still use (divisibility / fit classes).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: check how harmonically it divides the leftover.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 35.0; // next item exactly fills this bin
            } else if slack <= tenth {
                score -= 18.0;
            } else if slack <= fifth {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: dead space risk.
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current
    // leftovers are genuinely bad (all open bins badly fragmented).
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual < fifth as f64 && open_bins_count > 0 {
            // Open bins are nearly full: opening a new bin is reasonable.
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference for fuller-than-average bins (balance residual mass).
    score += (mean_residual - pr) * 0.05;

    // Small modulo-based tiebreaker on post_residual classes to break
    // ties deterministically toward cleaner harmonic splits.
    score += (post_residual % (bin_capacity / 50).max(1)) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since no item (min size 1..10 regime) can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // but a brand-new empty bin candidate (residual == capacity) gets a
    // mild handicap so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0;
        // Last-chance bin: strongly prefer using the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward using bins whose residual is close to the item (good coupling).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 10.0 * (1.0 - tightness);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0; // residual unusable for lookahead item
    }

    // Mild pressure from number of open bins: prefer filling existing bins
    // rather than spreading; slight time decay to allow new bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // to keep residuals balanced, unless it's a near-perfect fit.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}
